  "type": "object",
  "properties": {
    "sequence": {
      "type": "array",
      "maxItems": 10,
      "items": {
        "type": "string",
        "enum": [
          "visitor_lumos",
          "learner_reparo",
          "learner_lumos",
          "save_reload",
          "observe_mark",
          "learner_nox",
          "leave"
        ]
      }
    },
    "finalState": {
      "type": "object",
      "properties": {
        "learnerLocation": {
          "type": "string",
          "enum": [
            "storage",
            "outside"
          ]
        },
        "light": {
          "type": "string",
          "enum": [
            "on",
            "off"
          ]
        },
        "observedMark": {
          "type": "boolean"
        },
        "savedWhileLit": {
          "type": "boolean"
        },
        "rejectedCasts": {
          "type": "integer"
        },
        "xp": {
          "type": "integer"
        },
        "coins": {
          "type": "integer"
        }
      },
      "required": [
        "learnerLocation",
        "light",
        "observedMark",
        "savedWhileLit",
        "rejectedCasts",
        "xp",
        "coins"
      ],
      "additionalProperties": false
    },
    "explanation": {
      "type": "string",
      "maxLength": 400
    }
  },
  "required": [
    "sequence",
    "finalState",
    "explanation"
  ],
  "additionalProperties": false
}

